  fixture.loginAs(payer);payments.approve(payment);fixture.loginAs(world.superAdminUserId());assertThat(capacity.preview(scope,FinanceGlSettlementCapacityPort.Mode.EXPLICIT_GL_SOURCE,List.of(opening.reference())).availableLocal()).isEqualByComparingTo("4300");assertThat(db.queryForObject("SELECT amount_balance FROM ar_ap_ledger WHERE id=?",BigDecimal.class,ledger)).isEqualByComparingTo("600");assertThat(db.queryForObject("SELECT balance_current FROM accounts WHERE id=?",BigDecimal.class,bankAccount)).isEqualByComparingTo("2000");assertThat(db.queryForObject("SELECT initial_state::text FROM legacy_finance_import_sources WHERE target_id=?",String.class,ledger)).isEqualTo(proofBefore);
  assertThatThrownBy(()->links.withdraw(review,"还有真实付款，不能撤掉来源对应")).isInstanceOf(ApiException.class);fixture.loginAs(payer);payments.reverse(payment);fixture.loginAs(world.superAdminUserId());links.withdraw(review,"真实付款按原链反向后撤回关系，原金额及原始资料保留");assertThat(db.queryForObject("SELECT count(*) FROM v_finance_native_partial_gl_allocations WHERE entry_id=?",Integer.class,opening.reference().entryId())).isZero();assertThat(db.queryForObject("SELECT amount_local FROM finance_gl_entry_allocations WHERE entry_id=? AND allocation_no=?",BigDecimal.class,opening.reference().entryId(),opening.reference().allocationNo())).isEqualByComparingTo("5000");
