  assertThat(db.queryForObject("SELECT status FROM finance_native_legacy_opening_reviews WHERE id=?",String.class,second)).isEqualTo("DRAFT");assertThat(db.queryForObject("SELECT count(*) FROM finance_native_legacy_opening_parts WHERE review_id=?",Integer.class,second)).isZero();
