 private FinanceGlSettlementCapacityPort.Receipt reserve(FinanceGlSettlementCapacityPort.Scope scope,FinanceGlSettlementCapacityPort.SourceRef source,BigDecimal amount,FinanceGlSettlementCapacityPort.Owner owner){var preview=capacity.preview(scope,FinanceGlSettlementCapacityPort.Mode.EXPLICIT_GL_SOURCE,List.of(source));assertThat(preview.issues()).isEmpty();return capacity.reserve(new FinanceGlSettlementCapacityPort.Reservation(UUID.randomUUID(),owner,scope,FinanceGlSettlementCapacityPort.Mode.EXPLICIT_GL_SOURCE,preview.fingerprint(),amount,amount,List.of(new FinanceGlSettlementCapacityPort.SourceAmount(source,amount,amount)),"协议夹具明确原源，仅核对公共预算占用"));}
 private UUID legacy(int legacySupplier,String total,String settled,String unpaid)throws Exception{
  int sourceId=970412+db.queryForObject("SELECT count(*) FROM legacy_finance_import_sources WHERE source_kind='AP_OPENING'",Integer.class);ObjectNode raw=(ObjectNode)new ObjectMapper().readTree(LegacyFinanceImportFixture.source("m_out.csv"));raw.put("legacy_id",sourceId);raw.put("bill_no","ANON-VERIFIED-OLD-OPENING-"+sourceId);raw.put("supplier_legacy_id",legacySupplier);raw.put("currency_legacy_id",1);raw.put("exchange_rate",1);raw.put("total",n(total));raw.put("settled",n(settled));raw.put("balance",n(unpaid));
  return transactions.execute(t->{UUID run=LegacyFinanceImportFixture.context(db);UUID result=db.queryForObject("SELECT fn_import_legacy_finance_source(?, 'AP_OPENING',?::jsonb)",UUID.class,run,raw.toString());db.update("UPDATE legacy_migration_runs SET status='SUCCESS',finished_at=now() WHERE run_id=?",run);return result;});
 }
 private static com.uten.imp.features.finance.payment.dto.FinancePaymentSaveRequest payment(UUID supplier,UUID ledger,UUID currency,UUID account){var p=new com.uten.imp.features.finance.payment.dto.FinancePaymentSaveRequest();p.setBillDate(BusinessTime.today());p.setSupplierId(supplier);p.setCurrencyId(currency);p.setExchangeRate(BigDecimal.ONE);p.setAccountId(account);p.setAccountCurrencyId(currency);p.setAccountAmount(n("100"));p.setAmountOriginal(n("100"));p.setBankFeeAccountAmount(BigDecimal.ZERO);p.setBankBookedAt(OffsetDateTime.now());p.setBankReference("ANON-REAL-LEGACY-BANK");p.setCreateIdempotencyKey(UUID.randomUUID().toString());var line=new com.uten.imp.features.finance.payment.dto.FinancePaymentLineInput();line.setAppliedLedgerId(ledger);line.setSupplierId(supplier);line.setAmountOriginal(n("100"));p.setItems(List.of(line));return p;}
 private static byte[] balance()throws IOException{try(var b=new HSSFWorkbook();var out=new ByteArrayOutputStream()){var s=b.createSheet("科目余额");var h=s.createRow(0);var labels=List.of("会计年度","会计期间","科目编码","科目名称","外币名称","期初借方","期初贷方","本期发生借方","本期发生贷方","期末借方","期末贷方");for(int c=0;c<labels.size();c++){h.createCell(c).setCellValue(labels.get(c));}String[]codes={"1001","1002","2202","3001","220202"};double[][]v={{7000,0,0,0,7000,0},{2000,0,100,0,2100,0},{0,5000,0,0,0,5000},{0,2000,0,100,0,2100},{0,2000,0,0,0,2000}};for(int i=0;i<5;i++){var r=s.createRow(i+1);r.createCell(0).setCellValue(2025);r.createCell(1).setCellValue("月份：2025.02-2025.02");r.createCell(2).setCellValue(codes[i]);r.createCell(3).setCellValue("匿名真实期初科目"+codes[i]);r.createCell(4).setCellValue(codes[i].equals("220202")?"明确会计币别属性":"");for(int c=0;c<6;c++)r.createCell(c+5).setCellValue(v[i][c]);}b.write(out);return out.toByteArray();}}
 private static byte[] vouchers()throws IOException{try(var b=new HSSFWorkbook();var out=new ByteArrayOutputStream()){var s=b.createSheet("原凭证");var h=s.createRow(0);for(int c=0;c<82;c++){h.createCell(c).setCellValue("F"+(c+1)+"原字段");}h.createCell(82).setCellValue("凭证输出：ANON：T01：匿名：2025");for(int i=0;i<2;i++){var r=s.createRow(i+1);Map.of(0,"2025-02-28",1,"记",2,"001",4,"真实期内资本入账",5,i==0?"1002":"3001",48,"T01",49,"匿名").forEach((c,v)->r.createCell(c).setCellValue(v));r.createCell(i==0?6:7).setCellValue(100);r.createCell(50).setCellValue(2025);r.createCell(51).setCellValue(2);r.createCell(58).setCellValue(i+1);r.createCell(80).setCellValue(i+1);r.createCell(81).setCellValue(1);r.createCell(61).setCellValue("原源科目");}b.write(out);return out.toByteArray();}}
 private static BigDecimal n(String value){return new BigDecimal(value);}
